// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import {
    StreamReferenceModeTypes as M
} from "../../interfaces/stream/preservation/StreamReferenceModeTypes.sol";
import {
    IStreamReferenceModePayloadPreparation as P
} from "../../interfaces/stream/preservation/IStreamReferenceModePayloadPreparation.sol";
import {
    StreamReferenceModePayloadEncoding as Encoding
} from "./StreamReferenceModePayloadEncoding.sol";
import {
    StreamReferenceRenderPreparation as Environment
} from "./StreamReferenceRenderPreparation.sol";
import { StreamSnapshotManifestBytes as Bytes } from "../records/StreamSnapshotManifestBytes.sol";
import { StreamSchemaDocumentStore as Store } from "../metadata/StreamSchemaDocumentStore.sol";

/// @notice Permissionless immutable preparation. Final publication still performs every live check.
library StreamReferenceModePayloadPreparation {
    struct PublicationCarrier {
        P.PublicationDescriptor descriptor;
        Bytes.Manifest canonical;
    }

    struct State {
        mapping(bytes32 => PublicationCarrier) publications;
        mapping(bytes32 => Bytes.Manifest) payloads;
    }

    event ReferenceModePublicationPrepared(
        uint16 schemaVersion, bytes32 indexed preparationId, P.PublicationDescriptor descriptor
    );
    event ReferenceModePayloadPrepared(
        uint16 schemaVersion,
        bytes32 indexed preparationId,
        bytes32 indexed publicationPreparationId,
        bytes32 payloadHash,
        uint32 payloadBytes
    );

    function preparePublication(
        State storage state,
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        address store,
        bytes32 storeHash,
        bytes calldata original
    ) public returns (bytes32 id) {
        _pin(store, storeHash);
        R.Publication memory p = abi.decode(original[4:], (R.Publication));
        bytes memory raw = abi.encode(p);
        if (raw.length == 0 || raw.length > 524288) revert M.InvalidModeEvidence();
        bytes32 hash = keccak256(raw);
        id = Encoding.publicationId(hash, uint32(raw.length));
        PublicationCarrier storage saved = state.publications[id];
        if (saved.canonical.contentHash != 0) {
            _publication(saved, hash, uint32(raw.length));
            Bytes.requireIntact(saved.canonical);
            _environment(inventories, saved.descriptor);
            return id;
        }
        P.PublicationDescriptor memory descriptor = P.PublicationDescriptor(
            hash,
            uint32(raw.length),
            Environment.environmentIdInternal(p.environment),
            p.environment.manifestHash,
            p.environment.manifestBytes
        );
        _environment(inventories, descriptor);
        for (uint256 i; i < p.captures.length; ++i) {
            if (p.captures[i].environmentManifestHash != descriptor.environmentHash) {
                revert M.InvalidModeEvidence();
            }
        }
        Bytes.retain(saved.canonical, store, raw);
        saved.descriptor = descriptor;
        emit ReferenceModePublicationPrepared(1, id, descriptor);
    }

    function preparePayload(
        State storage state,
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        address store,
        bytes32 storeHash,
        bytes calldata original
    ) public returns (bytes32 id) {
        _pin(store, storeHash);
        (
            bytes32 publicationId,
            R.Receipt memory receipt,
            R.SourceFacts memory source,
            M.Evidence memory evidence,
            M.Facts memory facts
        ) = abi.decode(original[4:], (bytes32, R.Receipt, R.SourceFacts, M.Evidence, M.Facts));
        PublicationCarrier storage saved = state.publications[publicationId];
        P.PublicationDescriptor memory descriptor = saved.descriptor;
        if (
            publicationId
                != Encoding.publicationId(descriptor.publicationHash, descriptor.publicationBytes)
        ) revert M.InvalidModeEvidence();
        _publication(saved, descriptor.publicationHash, descriptor.publicationBytes);
        Encoding.normalize(receipt);
        bytes memory encodedReceipt = abi.encode(receipt);
        bytes[5] memory tails;
        tails[0] = Bytes.read(saved.canonical);
        tails[1] = abi.encode(source);
        tails[2] = abi.encode(evidence);
        tails[3] = abi.encode(facts);
        tails[4] = abi.encode(_environment(inventories, descriptor));
        id = Encoding.payloadId(
            Encoding.components(descriptor, encodedReceipt, tails[1], tails[2], tails[3])
        );
        if (state.payloads[id].contentHash != 0) {
            Bytes.requireIntact(state.payloads[id]);
            return id;
        }
        bytes memory canonical = Encoding.assemble(encodedReceipt, tails);
        bytes32 hash = _retain(state.payloads[id], store, canonical);
        emit ReferenceModePayloadPrepared(1, id, publicationId, hash, uint32(canonical.length));
    }

    /// @dev Only the actual publication worker calls this with hashes derived from its full typed
    /// input and newly validated facts. A cache miss preserves the original monolithic behavior.
    function lookup(
        State storage state,
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        bytes32 publicationHash,
        uint32 publicationBytes,
        R.Receipt memory receipt,
        R.SourceFacts memory source,
        M.Evidence memory evidence,
        M.Facts memory facts
    ) public view returns (bytes memory) {
        PublicationCarrier storage saved = state.publications[
            Encoding.publicationId(publicationHash, publicationBytes)
        ];
        if (saved.canonical.contentHash == 0) return new bytes(0);
        _publication(saved, publicationHash, publicationBytes);
        Encoding.normalize(receipt);
        bytes32 id = Encoding.payloadId(
            Encoding.components(
                saved.descriptor,
                abi.encode(receipt),
                abi.encode(source),
                abi.encode(evidence),
                abi.encode(facts)
            )
        );
        if (state.payloads[id].contentHash == 0) return new bytes(0);
        Bytes.requireIntact(saved.canonical);
        _environment(inventories, saved.descriptor);
        return Bytes.read(state.payloads[id]);
    }

    function publicationEncoded(State storage state, bytes32 id)
        public
        view
        returns (bytes memory)
    {
        PublicationCarrier storage saved = state.publications[id];
        _publication(saved, saved.descriptor.publicationHash, saved.descriptor.publicationBytes);
        if (
            id
                != Encoding.publicationId(
                    saved.descriptor.publicationHash, saved.descriptor.publicationBytes
                )
        ) revert M.InvalidModeEvidence();
        return abi.encode(saved.descriptor, Bytes.read(saved.canonical));
    }

    function payload(State storage state, bytes32 id) public view returns (bytes memory) {
        return Bytes.read(state.payloads[id]);
    }

    function _publication(PublicationCarrier storage saved, bytes32 hash, uint32 size)
        private
        view
    {
        if (
            hash == 0 || size == 0 || saved.descriptor.publicationHash != hash
                || saved.descriptor.publicationBytes != size || saved.canonical.contentHash != hash
                || saved.canonical.byteLength != size
        ) revert M.InvalidModeEvidence();
    }

    function _environment(
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        P.PublicationDescriptor memory p
    ) private view returns (bytes memory raw) {
        Bytes.Manifest storage saved = inventories[p.environmentId];
        if (
            p.environmentHash == 0 || p.environmentBytes == 0
                || saved.contentHash != p.environmentHash || saved.byteLength != p.environmentBytes
        ) revert M.InvalidModeEvidence();
        raw = Bytes.read(saved);
    }

    function _pin(address store, bytes32 hash) private view {
        if (store.code.length == 0 || store.codehash != hash) revert R.ReferenceDependency(store);
    }

    /// @dev Same fixed-maximum retention checks and writes as Bytes.retain. Keep the assembled
    /// payload in this frame and reuse one chunk scratch buffer instead of copying the full
    /// payload through the public library ABI and allocating a new buffer for every chunk.
    function _retain(Bytes.Manifest storage saved, address store, bytes memory canonical)
        private
        returns (bytes32 hash)
    {
        uint256 length = canonical.length;
        if (saved.byteLength != 0 || length == 0 || length > 524288) {
            revert Bytes.InvalidSnapshotManifest();
        }
        hash = keccak256(canonical);
        bytes memory scratch = new bytes(8193);
        for (uint256 offset; offset < length; offset += 8192) {
            uint256 size = length - offset;
            if (size > 8192) size = 8192;
            bytes32 chunkHash;
            assembly ("memory-safe") {
                chunkHash := keccak256(add(add(canonical, 32), offset), size)
            }
            (address pointer, uint32 storedLength) = Store(store).chunk(chunkHash);
            if (pointer == address(0) || storedLength != size) {
                revert Bytes.SnapshotChunkUnavailable(chunkHash);
            }
            if (pointer.code.length != size + 1) revert Bytes.SnapshotChunkChanged(pointer);
            bytes32 actual;
            assembly ("memory-safe") {
                extcodecopy(pointer, add(scratch, 32), 0, add(size, 1))
                actual := keccak256(add(scratch, 33), size)
            }
            if (scratch[0] != 0 || actual != chunkHash) {
                revert Bytes.SnapshotChunkChanged(pointer);
            }
            saved.pointers.push(pointer);
            saved.chunkHashes.push(chunkHash);
        }
        saved.contentHash = hash;
        saved.byteLength = uint32(length);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import {
    StreamReferenceModeTypes as M
} from "../../interfaces/stream/preservation/StreamReferenceModeTypes.sol";
import {
    IStreamReferenceModePayloadPreparation as P
} from "../../interfaces/stream/preservation/IStreamReferenceModePayloadPreparation.sol";

/// @notice Original payload ABI assembled from already authenticated canonical tuple encodings.
library StreamReferenceModePayloadEncoding {
    struct Components {
        bytes32 publicationHash;
        uint32 publicationBytes;
        bytes32 receiptHash;
        uint32 receiptBytes;
        bytes32 sourceHash;
        uint32 sourceBytes;
        bytes32 evidenceHash;
        uint32 evidenceBytes;
        bytes32 factsHash;
        uint32 factsBytes;
        bytes32 environmentHash;
        uint32 environmentBytes;
    }

    function normalize(R.Receipt memory r) internal pure {
        r.recordHash = 0;
        r.recordChainHash = 0;
        r.payloadHash = 0;
        r.payloadBytes = 0;
        r.recordedAt = 0;
    }

    function publicationId(bytes32 hash, uint32 size) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_MODE_PUBLICATION_PREPARATION_V1"),
                block.chainid,
                address(this),
                hash,
                size
            )
        );
    }

    function components(
        P.PublicationDescriptor memory p,
        bytes memory receipt,
        bytes memory source,
        bytes memory evidence,
        bytes memory facts
    ) internal pure returns (Components memory c) {
        c = Components(
            p.publicationHash,
            p.publicationBytes,
            keccak256(receipt),
            uint32(receipt.length),
            keccak256(source),
            uint32(source.length),
            keccak256(evidence),
            uint32(evidence.length),
            keccak256(facts),
            uint32(facts.length),
            p.environmentHash,
            p.environmentBytes
        );
        if (
            receipt.length != 640 || source.length > 524288 || evidence.length > 524288
                || facts.length > 524288
        ) {
            revert M.InvalidModeEvidence();
        }
    }

    function payloadId(Components memory c) internal view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_MODE_PAYLOAD_PREPARATION_V1"),
                block.chainid,
                address(this),
                c
            )
        );
    }

    /// @dev Each dynamic tuple is the compiler's abi.encode(tuple): its leading offset is 32.
    /// Receipt is exactly twenty static words. The original payload head is therefore 26 words:
    /// domain, Publication offset, Receipt, SourceFacts/Evidence/Facts/environment offsets.
    function assemble(bytes memory receipt, bytes[5] memory tails)
        internal
        pure
        returns (bytes memory out)
    {
        if (receipt.length != 640) revert M.InvalidModeEvidence();
        uint256 length = 832;
        for (uint256 i; i < 5; ++i) {
            bytes memory tail = tails[i];
            uint256 offset;
            assembly ("memory-safe") { offset := mload(add(tail, 32)) }
            if (tail.length < 64 || tail.length % 32 != 0 || offset != 32) {
                revert M.InvalidModeEvidence();
            }
            length += tail.length - 32;
        }
        if (length > 524288) revert M.InvalidModeEvidence();
        out = new bytes(length);
        bytes32 domain = keccak256("6529STREAM_REFERENCE_MODE_PAYLOAD_V1");
        assembly ("memory-safe") { mstore(add(out, 32), domain) }
        _copy(out, 64, receipt, 0, 640);
        uint256 cursor = 832;
        for (uint256 i; i < 5; ++i) {
            uint256 word = i == 0 ? 1 : 21 + i;
            assembly ("memory-safe") { mstore(add(add(out, 32), mul(word, 32)), cursor) }
            uint256 size = tails[i].length - 32;
            _copy(out, cursor, tails[i], 32, size);
            cursor += size;
        }
    }

    /// @dev All copied spans are complete ABI words inside newly allocated, length-checked bytes.
    function _copy(bytes memory out, uint256 at, bytes memory source, uint256 skip, uint256 size)
        private
        pure
    {
        assembly ("memory-safe") {
            let dest := add(add(out, 32), at)
            let src := add(add(source, 32), skip)
            let end := add(dest, size)
            for { } lt(dest, end) {
                dest := add(dest, 32)
                src := add(src, 32)
            } {
                mstore(dest, mload(src))
            }
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamReferenceModeTypes as M
} from "../../interfaces/stream/preservation/StreamReferenceModeTypes.sol";
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import { StreamReferenceModeProof } from "./StreamReferenceModeProof.sol";
import { StreamReferenceRenderSourceReads } from "./StreamReferenceRenderSourceReads.sol";
import { StreamReferenceRenderPreparation } from "./StreamReferenceRenderPreparation.sol";
import { StreamSnapshotManifestBytes as Bytes } from "../records/StreamSnapshotManifestBytes.sol";
import { StreamReferenceModeInput as Input } from "./StreamReferenceModeInput.sol";
import {
    StreamReferenceModePayloadPreparation as Payload
} from "./StreamReferenceModePayloadPreparation.sol";

/// @notice Fixed mode tuple decoding; the host retains candidate/authority checks and all writes.
library StreamReferenceModePreparation {
    struct Prepared {
        bytes32 sourcesHash;
        M.Facts mode;
        bytes canonical;
        bytes evidence;
    }

    function prepare(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        R.Receipt memory receipt,
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        bytes calldata original,
        bool writing
    ) public view returns (Prepared memory result) {
        R.Publication memory p;
        M.Evidence memory evidence;
        R.SourceFacts memory source;
        (result, p, evidence, source) = _validate(d, bindings, receipt, original, writing);
        result.canonical = StreamReferenceModeProof.payload(
            p, receipt, source, evidence, result.mode, _environment(inventories, p.environment)
        );
    }

    function prepareStaged(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        R.Receipt memory receipt,
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        Payload.State storage preparedPayloads,
        bytes calldata original,
        bool writing
    ) public view returns (Prepared memory result) {
        R.Publication memory p;
        M.Evidence memory evidence;
        R.SourceFacts memory source;
        (result, p, evidence, source) = _validate(d, bindings, receipt, original, writing);
        bytes memory encoded = abi.encode(p);
        if (encoded.length > 524288) revert M.InvalidModeEvidence();
        result.canonical = Payload.lookup(
            preparedPayloads,
            inventories,
            keccak256(encoded),
            uint32(encoded.length),
            receipt,
            source,
            evidence,
            result.mode
        );
        if (result.canonical.length == 0) {
            result.canonical = StreamReferenceModeProof.payload(
                p, receipt, source, evidence, result.mode, _environment(inventories, p.environment)
            );
        }
    }

    function _validate(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        R.Receipt memory receipt,
        bytes calldata original,
        bool writing
    )
        private
        view
        returns (
            Prepared memory result,
            R.Publication memory p,
            M.Evidence memory evidence,
            R.SourceFacts memory source
        )
    {
        // Both original mode write/preview selectors begin with this exact pair. Preview's
        // trailing recorder is consumed by the host before this fixed decoder is called.
        (p, evidence) = abi.decode(original[4:], (R.Publication, M.Evidence));
        source = StreamReferenceRenderSourceReads.requireModeSourceInputs(
            d, StreamReferenceRenderSourceReads.project(p), false
        );
        result.mode = StreamReferenceModeProof.requireEvidenceProjected(
            d, bindings, Input.project(p, Input.contextHash(d, p)), source, evidence, false
        );
        result.sourcesHash = StreamReferenceModeProof.sourceHash(d, bindings, source, result.mode);
        if (writing && (p.expectedSourcesHash == 0 || p.expectedSourcesHash != result.sourcesHash))
        {
            revert R.InvalidReferenceRender();
        }
        p.expectedSourcesHash = result.sourcesHash;
        receipt.sourcesHash = result.sourcesHash;
        result.evidence = abi.encode(evidence);
    }

    /// @dev Derive the complete typed input's exact preparation identity here. Transporting
    /// that large input to another worker solely to derive this same key is unnecessary.
    /// The only reused value is the immutable, self-verified canonical environment bytes.
    function _environment(
        mapping(bytes32 => Bytes.Manifest) storage inventories,
        R.Environment memory e
    ) private view returns (bytes memory) {
        bytes32 id = StreamReferenceRenderPreparation.environmentIdInternal(e);
        if (inventories[id].contentHash != 0) return Bytes.read(inventories[id]);
        return StreamReferenceRenderPreparation.environment(inventories, e);
    }

    function current(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        Bytes.Manifest storage publication,
        Bytes.Manifest storage saved
    ) public view returns (bytes32 sourcesHash, M.Facts memory facts) {
        R.Publication memory p = abi.decode(Bytes.read(publication), (R.Publication));
        M.Evidence memory evidence = _evidence(saved);
        R.SourceFacts memory source = StreamReferenceRenderSourceReads.requireModeSourceInputs(
            d, StreamReferenceRenderSourceReads.project(p), true
        );
        facts = StreamReferenceModeProof.requireEvidenceProjected(
            d, bindings, Input.project(p, Input.contextHash(d, p)), source, evidence, true
        );
        sourcesHash = StreamReferenceModeProof.sourceHash(d, bindings, source, facts);
    }

    function evidenceEncoded(Bytes.Manifest storage saved, M.Facts storage facts)
        public
        view
        returns (bytes memory)
    {
        return abi.encode(_evidence(saved), facts);
    }

    /// @dev Original current-source comparison, in the same order, without transporting the
    /// large Facts tuple back through the host solely to encode and compare it again.
    function requireCurrent(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        Bytes.Manifest storage publication,
        Bytes.Manifest storage evidence,
        M.Facts storage savedFacts,
        Bytes.Manifest storage payload,
        R.Receipt storage receipt
    ) public view {
        (bytes32 sourcesHash, M.Facts memory mode) = current(d, bindings, publication, evidence);
        if (
            sourcesHash != receipt.sourcesHash
                || keccak256(abi.encode(mode)) != keccak256(abi.encode(savedFacts))
                || Bytes.requireIntact(payload) != receipt.payloadHash
        ) revert M.InvalidModeEvidence();
    }

    function _evidence(Bytes.Manifest storage saved) private view returns (M.Evidence memory e) {
        bytes memory raw = Bytes.read(saved);
        e = abi.decode(raw, (M.Evidence));
        if (keccak256(raw) != keccak256(abi.encode(e))) revert M.InvalidModeEvidence();
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../interfaces/stream/preservation/IStreamReferenceModePublication.sol";
import { StreamReferenceModePreparation } from "./StreamReferenceModePreparation.sol";
import { StreamReferenceModePayloadPreparation } from "./StreamReferenceModePayloadPreparation.sol";
import {
    IStreamReferenceModePayloadPreparation
} from "../../interfaces/stream/preservation/IStreamReferenceModePayloadPreparation.sol";
import { StreamReferenceMetricStorage } from "./StreamReferenceMetricStorage.sol";
import { StreamReferenceModeStateReads } from "./StreamReferenceModeStateReads.sol";
import {
    IStreamReferenceMetricSupplement
} from "../../interfaces/stream/preservation/IStreamReferenceMetricSupplement.sol";
import {
    StreamReferenceMetricTypes as Metric
} from "../../interfaces/stream/preservation/StreamReferenceMetricTypes.sol";
import { StreamReferenceModeProof } from "./StreamReferenceModeProof.sol";
import { StreamReferenceModeDefinitionsRead } from "./StreamReferenceModeDefinitionsRead.sol";
import { StreamReferenceModeDefinitions } from "../records/StreamReferenceModeDefinitions.sol";
import "../../interfaces/stream/finality/IStreamArtworkFinalityComponents.sol";
import "../../interfaces/stream/modules/IStreamModule.sol";
import "./StreamReferenceRenderSourceReads.sol";
import "./StreamReferenceRenderRecordReads.sol";
import "./StreamReferenceRenderPreparation.sol";
import { StreamReferenceInventoryPreparation } from "./StreamReferenceInventoryPreparation.sol";
import {
    IStreamReferenceInventoryPreparation
} from "../../interfaces/stream/preservation/IStreamReferenceInventoryPreparation.sol";
import {
    IStreamReferenceEnvironmentPreparation
} from "../../interfaces/stream/preservation/IStreamReferenceEnvironmentPreparation.sol";
import "../records/StreamReferenceManifestJson.sol";
import "../records/StreamReferenceRenderDefinitionReads.sol";
import "../records/StreamSnapshotManifestBytes.sol";
import "../records/StreamRecordFamilies.sol";
import "../parameters/StreamGasParameterHost.sol";

/// @notice Original non-byte-exact reference observations with exact typed mode evidence.
/// @dev Publishing never changes artwork bytes. Bulk runtime objects remain externally archived;
///      complete original canonical manifests and ABI witnesses use actual immutable Store chunks.
contract StreamReferenceModePublication is
    IStreamReferenceModePublication,
    IStreamReferenceInventoryPreparation,
    IStreamReferenceEnvironmentPreparation,
    IStreamReferenceModePayloadPreparation,
    IStreamReferenceMetricSupplement,
    IStreamArtworkFinalityComponent,
    IStreamArtworkScopedFinalityComponent,
    IStreamModule,
    StreamGasParameterHost
{
    // Retain the original ABI error now emitted by the fixed writer-read worker.
    error ReferenceDependency(address target);
    bytes32 public constant READ_GAS = keccak256("6529STREAM_GGP_REFERENCE_READ_GAS");
    bytes32 public constant SOURCE_GAS = keccak256("6529STREAM_GGP_REFERENCE_SOURCE_GAS");
    bytes32 public constant SNAPSHOT_GAS = keccak256("6529STREAM_GGP_REFERENCE_SNAPSHOT_GAS");
    bytes32 public constant ARCHIVE_GAS = keccak256("6529STREAM_GGP_REFERENCE_ARCHIVE_GAS");
    address public immutable override core;
    address public immutable override metadataHost;
    address public immutable override metadataRouter;
    address public immutable override snapshots;
    address public immutable override archiveCoverage;
    uint256 public immutable deploymentChainId;
    bytes32 public immutable executorCodeHash;
    StreamReferenceRenderTypes.Dependencies private _fixed;
    mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) private _publications;
    mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) private _payloads;
    mapping(bytes32 => StreamReferenceRenderTypes.Receipt) private _receipts;
    mapping(uint256 => bytes32[]) private _history;
    mapping(uint256 => mapping(bytes32 => bool)) private _ids;
    mapping(uint256 => StreamReferenceRenderTypes.Lock) private _locks;
    bool private _entered;
    mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) private _fileInventories;
    mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) private _modeEvidence;
    StreamReferenceModeTypes.Dependencies private _modeBindings;
    mapping(bytes32 => StreamReferenceModeTypes.Facts) private _modeFacts;
    StreamReferenceMetricStorage.State private _metricSupplements;
    StreamReferenceModePayloadPreparation.State private _preparedModePayloads;

    constructor(
        StreamReferenceRenderTypes.Dependencies memory d,
        address executor,
        GasParameterConfig[4] memory configs,
        StreamReferenceModeTypes.Dependencies memory modeBindings
    ) StreamGasParameterHost(executor) {
        if (
            _registerGasParameter(configs[0]) != READ_GAS
                || _registerGasParameter(configs[1]) != SOURCE_GAS
                || _registerGasParameter(configs[2]) != SNAPSHOT_GAS
                || _registerGasParameter(configs[3]) != ARCHIVE_GAS
        ) {
            revert StreamReferenceRenderTypes.InvalidReferenceRender();
        }
        for (uint256 i; i < 4; ++i) {
            if (configs[i].failureClass != 1) {
                revert StreamReferenceRenderTypes.InvalidReferenceRender();
            }
        }
        _fixed = d;
        _modeBindings = modeBindings;
        core = d.targets[0];
        metadataHost = d.targets[1];
        metadataRouter = d.targets[4];
        snapshots = d.targets[5];
        archiveCoverage = d.targets[6];
        deploymentChainId = block.chainid;
        executorCodeHash = abi.decode(
            StreamFinalityRouterEvidence.read(
                metadataHost,
                abi.encodeWithSignature("executorCodeHash()"),
                32,
                configs[0].genesisValue
            ),
            (bytes32)
        );
        if (
            executorCodeHash == 0 || executor.codehash != executorCodeHash
                || abi.decode(
                        StreamFinalityRouterEvidence.read(
                            metadataHost,
                            abi.encodeWithSignature("governanceAuthority()"),
                            32,
                            configs[0].genesisValue
                        ),
                        (address)
                    ) != executor
        ) {
            revert StreamReferenceRenderTypes.InvalidReferenceRender();
        }
        StreamReferenceRenderSourceReads.validateDependencies(dependencies());
    }
    modifier guarded() {
        if (_entered) revert StreamReferenceRenderTypes.InvalidReferenceRender();
        _entered = true;
        _;
        _entered = false;
    }

    function supportsInterface(bytes4 id) external pure override returns (bool) {
        return id == type(IERC165).interfaceId
            || id == type(IStreamReferenceModePublication).interfaceId
            || id == type(IStreamReferenceInventoryPreparation).interfaceId
            || id == type(IStreamReferenceEnvironmentPreparation).interfaceId
            || id == type(IStreamReferenceModePayloadPreparation).interfaceId
            || id == type(IStreamReferenceMetricSupplement).interfaceId
            || id == type(IStreamArtworkFinalityComponent).interfaceId
            || id == type(IStreamArtworkScopedFinalityComponent).interfaceId
            || id == type(IStreamModule).interfaceId
            || id == type(IStreamGasParameterHost).interfaceId;
    }

    function dependencies()
        public
        view
        override
        returns (StreamReferenceRenderTypes.Dependencies memory d)
    {
        d = _fixed;
        d.readGas = gasParameter(READ_GAS);
        d.sourceGas = gasParameter(SOURCE_GAS);
        d.snapshotGas = gasParameter(SNAPSHOT_GAS);
        d.archiveGas = gasParameter(ARCHIVE_GAS);
    }

    function modeDependencies()
        external
        view
        override
        returns (StreamReferenceModeTypes.Dependencies memory)
    {
        return _modeBindings;
    }

    function publishMetricSupplement(bytes32 hash, Metric.Supplement calldata)
        external
        override
        guarded
        returns (bytes32)
    {
        _known(hash);
        StreamReferenceRenderTypes.Receipt memory r = _receipts[hash];
        requireCurrent(r.collectionId, hash, r.revision);
        if (_locks[r.collectionId].actionId != 0) {
            revert StreamReferenceRenderTypes.ReferenceLocked();
        }
        (uint8 cls, uint64 rev) = _authority(r.collectionId, msg.sender);
        StreamReferenceMetricStorage.Context memory c =
            StreamReferenceMetricStorage.Context(dependencies(), r, msg.sender, cls, rev);
        return StreamReferenceMetricStorage.publish(
            _metricSupplements, c, _publications[hash], _modeEvidence[hash], msg.data
        );
    }

    function metricSupplement(bytes32 hash)
        external
        view
        override
        returns (bytes memory, Metric.Receipt memory)
    {
        _known(hash);
        bytes memory raw = StreamReferenceMetricStorage.encoded(_metricSupplements, hash);
        assembly ("memory-safe") { return(add(raw, 32), mload(raw)) }
    }

    function requireMetricSupplement(bytes32 hash)
        external
        view
        override
        returns (Metric.Receipt memory)
    {
        _known(hash);
        StreamReferenceRenderTypes.Receipt memory r = _receipts[hash];
        requireCurrent(r.collectionId, hash, r.revision);
        bytes memory raw = StreamReferenceMetricStorage.requireEncoded(
            _metricSupplements, dependencies(), hash, _publications[hash], _modeEvidence[hash]
        );
        assembly ("memory-safe") { return(add(raw, 32), mload(raw)) }
    }

    function previewReference(StreamReferenceRenderTypes.Publication memory, address)
        external
        pure
        override
        returns (bytes32, bytes memory)
    {
        revert StreamReferenceModeTypes.InvalidModeEvidence();
    }

    function publishReference(StreamReferenceRenderTypes.Publication memory)
        external
        pure
        override
        returns (bytes32)
    {
        revert StreamReferenceModeTypes.InvalidModeEvidence();
    }

    function modeContextHash(StreamReferenceRenderTypes.Publication calldata p)
        external
        view
        override
        returns (bytes32)
    {
        return StreamReferenceModeProof.contextHash(dependencies(), p);
    }

    function previewModeReference(
        StreamReferenceRenderTypes.Publication calldata original,
        StreamReferenceModeTypes.Evidence calldata originalEvidence,
        address recorder
    ) external view override returns (bytes32 sourceHash, bytes memory canonical) {
        StreamReferenceRenderTypes.Publication calldata p = original;
        _candidate(p);
        StreamReferenceRenderTypes.Receipt memory r = _receipt(p, recorder);
        StreamReferenceRenderTypes.Dependencies memory d = dependencies();
        StreamReferenceModePreparation.Prepared memory result =
            StreamReferenceModePreparation.prepareStaged(
                d, _modeBindings, r, _fileInventories, _preparedModePayloads, msg.data, false
            );
        return (result.sourcesHash, result.canonical);
    }

    function publishModeReference(
        StreamReferenceRenderTypes.Publication calldata original,
        StreamReferenceModeTypes.Evidence calldata originalEvidence
    ) external override guarded returns (bytes32 hash) {
        StreamReferenceRenderTypes.Publication calldata p = original;
        _candidate(p);
        StreamReferenceRenderTypes.Receipt memory r = _receipt(p, msg.sender);
        StreamReferenceRenderTypes.Dependencies memory d = dependencies();
        _definitions(d);
        StreamReferenceModePreparation.Prepared memory result =
            StreamReferenceModePreparation.prepareStaged(
                d, _modeBindings, r, _fileInventories, _preparedModePayloads, msg.data, true
            );
        StreamReferenceModeTypes.Facts memory mode = result.mode;
        r.sourcesHash = result.sourcesHash;
        bytes memory canonical = result.canonical;
        r.payloadHash = keccak256(canonical);
        r.payloadBytes = uint32(canonical.length);
        r.recordedAt = uint64(block.timestamp);
        hash = keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_MODE_RECORD_V1"),
                deploymentChainId,
                address(this),
                core,
                metadataHost,
                p,
                r
            )
        );
        r.recordHash = hash;
        r.recordChainHash = keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_MODE_CHAIN_V1"),
                deploymentChainId,
                address(this),
                core,
                p.collectionId,
                p.expectedHead == 0 ? bytes32(0) : _receipts[p.expectedHead].recordChainHash,
                r.revision,
                hash
            )
        );
        StreamSnapshotManifestBytes.retain(_payloads[hash], d.targets[3], canonical);
        StreamSnapshotManifestBytes.retain(_publications[hash], d.targets[3], abi.encode(p));
        StreamSnapshotManifestBytes.retain(_modeEvidence[hash], d.targets[3], result.evidence);
        _modeFacts[hash] = mode;
        _receipts[hash] = r;
        _history[p.collectionId].push(hash);
        _ids[p.collectionId][p.referenceId] = true;
        emit ReferenceModePublished(1, hash, mode.mode, mode.evidenceHash, mode.interpretationHash);
        emit ReferenceRenderPublished(hash, p.collectionId, p.referenceId, r, p.manifestURI);
    }

    function currentReference(uint256 cid)
        public
        view
        override
        returns (StreamReferenceRenderTypes.Receipt memory)
    {
        return _receipts[_head(cid)];
    }

    function prepareFileInventory(
        StreamReferenceRenderTypes.PackageFile[] calldata rows,
        bool relative
    ) external override guarded returns (bytes32) {
        return StreamReferenceRenderPreparation.prepare(
            _fileInventories, _fixed.targets[3], _fixed.codeHashes[3], rows, relative
        );
    }

    function prepareFileInventoryPart(StreamReferenceRenderTypes.PackageFile[] calldata, bool)
        external
        override
        guarded
        returns (bytes32)
    {
        return StreamReferenceInventoryPreparation.preparePart(
            _fileInventories, _fixed.targets[3], _fixed.codeHashes[3], msg.data
        );
    }

    function prepareFileInventoryFromParts(StreamReferenceRenderTypes.PackageFile[] calldata, bool)
        external
        override
        guarded
        returns (bytes32)
    {
        return StreamReferenceInventoryPreparation.assemble(
            _fileInventories, _fixed.targets[3], _fixed.codeHashes[3], msg.data
        );
    }

    function preparedFileInventory(bytes32 id) external view override returns (bytes memory) {
        return StreamSnapshotManifestBytes.read(_fileInventories[id]);
    }

    function prepareEnvironment(StreamReferenceRenderTypes.Environment calldata)
        external
        override
        guarded
        returns (bytes32)
    {
        return StreamReferenceRenderPreparation.prepareEnvironment(
            _fileInventories, _fixed.targets[3], _fixed.codeHashes[3], msg.data
        );
    }

    function referenceRecord(bytes32 hash)
        external
        view
        override
        returns (
            StreamReferenceRenderTypes.Publication memory,
            StreamReferenceRenderTypes.Receipt memory
        )
    {
        _known(hash);
        bytes memory raw =
            StreamReferenceRenderRecordReads.recordBytes(_publications[hash], _receipts[hash]);
        assembly ("memory-safe") { return(add(raw, 32), mload(raw)) }
    }

    function prepareModePublication(StreamReferenceRenderTypes.Publication calldata)
        external
        override
        guarded
        returns (bytes32)
    {
        return StreamReferenceModePayloadPreparation.preparePublication(
            _preparedModePayloads,
            _fileInventories,
            _fixed.targets[3],
            _fixed.codeHashes[3],
            msg.data
        );
    }

    function prepareModePayload(
        bytes32,
        StreamReferenceRenderTypes.Receipt calldata,
        StreamReferenceRenderTypes.SourceFacts calldata,
        StreamReferenceModeTypes.Evidence calldata,
        StreamReferenceModeTypes.Facts calldata
    ) external override guarded returns (bytes32) {
        return StreamReferenceModePayloadPreparation.preparePayload(
                _preparedModePayloads,
                _fileInventories,
                _fixed.targets[3],
                _fixed.codeHashes[3],
                msg.data
            );
    }

    function preparedModePublication(bytes32 id)
        external
        view
        override
        returns (PublicationDescriptor memory, bytes memory)
    {
        bytes memory raw = StreamReferenceModePayloadPreparation.publicationEncoded(
            _preparedModePayloads, id
        );
        assembly ("memory-safe") { return(add(raw, 32), mload(raw)) }
    }

    function preparedModePayload(bytes32 id) external view override returns (bytes memory) {
        return StreamReferenceModePayloadPreparation.payload(_preparedModePayloads, id);
    }

    function referencePayload(bytes32 hash) external view override returns (bytes memory) {
        _known(hash);
        return StreamSnapshotManifestBytes.read(_payloads[hash]);
    }

    function referenceCount(uint256 cid) external view override returns (uint256) {
        return _history[cid].length;
    }

    function referenceAt(uint256 cid, uint256 index) external view override returns (bytes32) {
        return _history[cid][index];
    }

    function referenceLock(uint256 cid)
        external
        view
        override
        returns (StreamReferenceRenderTypes.Lock memory)
    {
        return _locks[cid];
    }

    function requireCurrent(uint256 cid, bytes32 hash, uint64 revision)
        public
        view
        override
        returns (StreamReferenceRenderTypes.Receipt memory r)
    {
        _known(hash);
        r = _receipts[hash];
        if (_head(cid) != hash || r.collectionId != cid || r.revision != revision) {
            revert StreamReferenceRenderTypes.ReferenceLineage(hash, _head(cid));
        }
        StreamReferenceRenderTypes.Dependencies memory d = dependencies();
        StreamReferenceModePreparation.requireCurrent(
            d,
            _modeBindings,
            _publications[hash],
            _modeEvidence[hash],
            _modeFacts[hash],
            _payloads[hash],
            _receipts[hash]
        );
    }

    function lockTransition(uint256 cid)
        public
        view
        override
        returns (bytes32 scope, bytes32 oldHash, bytes32 newHash)
    {
        StreamReferenceRenderTypes.Receipt memory r = currentReference(cid);
        if (r.recordHash == 0 || _locks[cid].actionId != 0) {
            revert StreamReferenceRenderTypes.ReferenceLocked();
        }
        bytes32 supplement;
        if (_modeFacts[r.recordHash].mode == StreamReferenceModeTypes.Mode.PERCEPTUAL_TOLERANCE) {
            supplement = _metricHash(r.recordHash);
        }
        return StreamReferenceModeStateReads.lock(
            deploymentChainId, core, cid, r.recordHash, r.revision, supplement
        );
    }

    function lockReference(uint256 cid) external override guarded {
        if (msg.sender != governanceAuthority || governanceAuthority.codehash != executorCodeHash) {
            revert StreamReferenceRenderTypes.ReferenceAuthority(msg.sender);
        }
        (bytes32 scope, bytes32 oldHash, bytes32 newHash) = lockTransition(cid);
        bytes memory raw = StreamFinalityRouterEvidence.read(
            governanceAuthority,
            abi.encodeCall(IStreamGovernedParameterAuthority.currentAction, ()),
            192,
            gasParameter(READ_GAS)
        );
        (
            bool executing,
            bytes32 id,
            uint8 cls,
            bytes32 actualScope,
            bytes32 actualOld,
            bytes32 actualNew
        ) = abi.decode(raw, (bool, bytes32, uint8, bytes32, bytes32, bytes32));
        if (
            keccak256(raw)
                    != keccak256(abi.encode(executing, id, cls, actualScope, actualOld, actualNew))
                || !executing || id == 0 || cls != 2 || actualScope != scope || actualOld != oldHash
                || actualNew != newHash || block.timestamp == 0
                || block.timestamp > type(uint64).max
        ) {
            revert StreamReferenceRenderTypes.ReferenceAuthority(msg.sender);
        }
        StreamReferenceRenderTypes.Receipt memory r = currentReference(cid);
        requireCurrent(cid, r.recordHash, r.revision);
        _locks[cid] =
            StreamReferenceRenderTypes.Lock(r.recordHash, r.revision, id, uint64(block.timestamp));
        emit ReferenceRenderLocked(r.recordHash, cid, id, r.revision);
    }

    function finalityState(uint256 cid)
        public
        view
        override
        returns (StreamFinalityComponentState memory)
    {
        StreamReferenceRenderTypes.Receipt memory r = currentReference(cid);
        requireCurrent(cid, r.recordHash, r.revision);
        StreamReferenceRenderTypes.Lock memory l = _locks[cid];
        if (l.actionId == 0 || l.recordHash != r.recordHash || l.revision != r.revision) {
            revert StreamReferenceRenderTypes.ReferenceLocked();
        }
        bytes32 supplement;
        if (_modeFacts[r.recordHash].mode == StreamReferenceModeTypes.Mode.PERCEPTUAL_TOLERANCE) {
            supplement = _metricHash(r.recordHash);
        }
        return StreamReferenceModeStateReads.component(
            _receipts[r.recordHash],
            _locks[cid],
            deploymentChainId,
            core,
            cid,
            streamModuleVersion(),
            supplement
        );
    }

    function _metricHash(bytes32 hash) private view returns (bytes32) {
        return StreamReferenceMetricStorage.requireHash(
            _metricSupplements, dependencies(), hash, _publications[hash], _modeEvidence[hash]
        );
    }

    function finalityStateForScope(StreamFinalityScope calldata scope)
        external
        view
        override
        returns (StreamFinalityComponentState memory)
    {
        if (
            scope.scopeType != StreamFinalityScopeType.COLLECTION || scope.collectionId == 0
                || scope.tokenId != 0 || scope.scopeId != 0
        ) {
            revert StreamReferenceRenderTypes.InvalidReferenceRender();
        }
        return finalityState(scope.collectionId);
    }

    function streamModuleType() external pure override returns (bytes32) {
        return keccak256("REFERENCE_RENDER");
    }

    function streamModuleVersion() public pure override returns (bytes32) {
        return keccak256("STREAM_REFERENCE_MODE_IMPLEMENTATION_V1");
    }

    function streamModuleInterfaceId() external pure override returns (bytes4) {
        return type(IStreamArtworkFinalityComponent).interfaceId;
    }

    function streamModuleSchemaHash() external pure override returns (bytes32) {
        return StreamReferenceModeDefinitions.SCHEMA_HASH;
    }

    function streamModuleSupersedes() external pure override returns (address) {
        return address(0);
    }

    function streamModuleCodeHash() external view override returns (bytes32) {
        return address(this).codehash;
    }

    function streamModuleDeploymentManifestHash() external view override returns (bytes32) {
        return keccak256(abi.encode(deploymentChainId, _fixed));
    }

    function streamModuleManifest() external pure override returns (string memory, bytes32) {
        return ("", StreamReferenceModeDefinitions.PROFILE_HASH);
    }

    function _receipt(StreamReferenceRenderTypes.Publication calldata p, address recorder)
        private
        view
        returns (StreamReferenceRenderTypes.Receipt memory r)
    {
        r.collectionId = p.collectionId;
        r.referenceId = p.referenceId;
        r.predecessor = p.expectedHead;
        r.revision = p.expectedRevision + 1;
        r.snapshotRecordHash = p.snapshotRecordHash;
        r.snapshotRevision = p.snapshotRevision;
        r.recorder = recorder;
        (r.authorizationClass, r.grantRevision) = _authority(p.collectionId, recorder);
        r.effectiveAt = p.effectiveAt;
        r.reasonHash = p.reasonHash;
        r.schemaHash = StreamReferenceModeDefinitions.SCHEMA_HASH;
        r.profileHash = StreamReferenceModeDefinitions.PROFILE_HASH;
        r.canonicalizationHash = StreamReferenceModeDefinitions.CANON_HASH;
    }

    function _authority(uint256 cid, address actor) private view returns (uint8 cls, uint64 rev) {
        if (actor == address(0)) revert StreamReferenceRenderTypes.ReferenceAuthority(actor);
        return
            StreamReferenceModeStateReads.authority(
                metadataHost, cid, actor, gasParameter(READ_GAS)
            );
    }

    function _candidate(StreamReferenceRenderTypes.Publication calldata p) private view {
        StreamReferenceModeStateReads.candidateHeader(
            StreamReferenceModeStateReads.Candidate(
                p.collectionId,
                p.referenceId,
                p.reasonHash,
                p.effectiveAt,
                p.expectedRevision,
                p.expectedHead,
                p.manifestURI
            ),
            _ids,
            _history,
            _locks
        );
    }

    function _definitions(StreamReferenceRenderTypes.Dependencies memory d) private view {
        StreamReferenceModeDefinitionsRead.requireDefinitions(d);
    }

    function referenceModeEvidence(bytes32 hash)
        external
        view
        override
        returns (StreamReferenceModeTypes.Evidence memory, StreamReferenceModeTypes.Facts memory)
    {
        _known(hash);
        bytes memory raw =
            StreamReferenceModePreparation.evidenceEncoded(_modeEvidence[hash], _modeFacts[hash]);
        assembly ("memory-safe") { return(add(raw, 32), mload(raw)) }
    }

    function referenceMode(bytes32 hash)
        external
        view
        override
        returns (StreamReferenceModeTypes.Mode, bytes32)
    {
        _known(hash);
        return (_modeFacts[hash].mode, _modeFacts[hash].evidenceHash);
    }

    function _head(uint256 cid) private view returns (bytes32) {
        uint256 n = _history[cid].length;
        return n == 0 ? bytes32(0) : _history[cid][n - 1];
    }

    function _known(bytes32 hash) private view {
        if (hash == 0 || _receipts[hash].recordHash != hash) {
            revert StreamReferenceRenderTypes.InvalidReferenceRender();
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
import {
    StreamReferenceModeTypes as M
} from "../../interfaces/stream/preservation/StreamReferenceModeTypes.sol";
import {
    StreamReferenceRenderTypes as R
} from "../../interfaces/stream/preservation/StreamReferenceRenderTypes.sol";
import { StreamReferenceRenderSourceReads } from "./StreamReferenceRenderSourceReads.sol";
import {
    StreamExternalArtifactTypes as E
} from "../../interfaces/stream/preservation/StreamExternalArtifactTypes.sol";
import { StreamMetadataRenderer } from "../metadata/StreamMetadataRenderer.sol";
import { StreamReferenceModeDefinitions } from "../records/StreamReferenceModeDefinitions.sol";
import { StreamReferenceModeCurated } from "./StreamReferenceModeCurated.sol";
import { StreamReferenceModeDefinitionsRead } from "./StreamReferenceModeDefinitionsRead.sol";
import { StreamReferenceModeInput as Input } from "./StreamReferenceModeInput.sol";

/// @notice Complete source-bound evidence for the two explicit non-byte-exact acceptance modes.
/// @dev The EVM validates original evidence and thresholds, not offchain browser/metric execution.
library StreamReferenceModeProof {
    function contextHash(R.Dependencies memory d, R.Publication memory p)
        public
        view
        returns (bytes32)
    {
        return Input.contextHash(d, p);
    }

    function requireEvidence(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        R.Publication memory p,
        R.SourceFacts memory source,
        M.Evidence memory w,
        bool current
    ) public view returns (M.Facts memory f) {
        return requireEvidenceProjected(
            d, bindings, Input.project(p, Input.contextHash(d, p)), source, w, current
        );
    }

    /// @dev The fixed preparation worker derives this projection from its one full decode.
    /// No publication authority or current-source check is cached or supplied by a new caller.
    function requireEvidenceProjected(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        Input.EvidenceInput memory p,
        R.SourceFacts memory source,
        M.Evidence memory w,
        bool current
    ) public view returns (M.Facts memory f) {
        StreamReferenceModeDefinitionsRead.requireDefinitions(d);
        if (
            (w.mode != M.Mode.PERCEPTUAL_TOLERANCE && w.mode != M.Mode.CURATED_EQUIVALENCE)
                || w.repeats.length != p.captures.length || w.repeats.length == 0
                || w.repeats.length > 2
        ) {
            revert M.InvalidModeEvidence();
        }
        f.mode = w.mode;
        f.evidenceHash = keccak256(abi.encode(w));
        f.repeats = new E.Coverage[](w.repeats.length);
        for (uint256 i; i < w.repeats.length; ++i) {
            f.repeats[i] = StreamReferenceRenderSourceReads.coverage(
                d, w.repeats[i].coverageHash, source.artistId, w.repeats[i].objectHash, current
            );
            StreamReferenceRenderSourceReads.requireCaptureObject(d, f.repeats[i]);
            if (f.repeats[i].sha256Digest != p.captures[i].repeatSha256) {
                revert M.InvalidModeEvidence();
            }
        }
        bytes32 context = p.contextHash;
        if (w.mode == M.Mode.PERCEPTUAL_TOLERANCE) {
            M.Curated memory empty;
            if (keccak256(abi.encode(w.curated)) != keccak256(abi.encode(empty))) {
                revert M.InvalidModeEvidence();
            }
            f.interpretationHash = StreamReferenceModeDefinitionsRead.metric(d, w.perceptual.metric);
            M.Perceptual memory m = w.perceptual;
            if (
                m.threshold < 0 || m.threshold > 1000000000 || m.scores.length != p.captures.length
                    || m.evaluatedAt == 0 || m.evaluatedAt > p.effectiveAt || m.reportHash == 0
            ) {
                revert M.InvalidModeEvidence();
            }
            StreamMetadataRenderer.requireValidUtf8ContentUri(
                "metricReportURI", m.reportURI, 2048, true
            );
            for (uint256 i; i < m.scores.length; ++i) {
                if (
                    m.scores[i] < m.threshold || m.scores[i] > 1000000000
                        || m.evaluatedAt < p.captures[i].capturedAt
                ) {
                    revert M.InvalidModeEvidence();
                }
            }
            // Full reproducible report preimage is retained in Evidence, including exact source context.
            if (
                m.reportHash
                    != keccak256(
                        abi.encode(
                            keccak256("6529STREAM_PERCEPTUAL_REPORT_V1"),
                            context,
                            m.metric,
                            m.threshold,
                            m.scores,
                            m.evaluatedAt
                        )
                    )
            ) revert M.InvalidModeEvidence();
        } else {
            M.Perceptual memory empty;
            if (keccak256(abi.encode(w.perceptual)) != keccak256(abi.encode(empty))) {
                revert M.InvalidModeEvidence();
            }
            (f.intentSelectionHash, f.conditionReceiptHash) =
                StreamReferenceModeCurated.requireEvidenceProjected(
                    d, bindings, p, source, w.curated
                );
            f.conditionRecordHash = w.curated.conditionRecordHash;
            f.interpretationHash = keccak256(
                abi.encode(
                    StreamReferenceModeDefinitions.CONDITION_HASH,
                    StreamReferenceModeDefinitions.PROPERTIES_HASH,
                    StreamReferenceModeDefinitions.CANON_HASH
                )
            );
        }
    }

    function sourceHash(
        R.Dependencies memory d,
        M.Dependencies memory bindings,
        R.SourceFacts memory source,
        M.Facts memory mode
    ) public view returns (bytes32) {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_MODE_SOURCES_V1"),
                d.chainId,
                address(this),
                d.targets,
                d.codeHashes,
                d.rendererCatalogId,
                d.rendererCatalogHash,
                bindings,
                source,
                mode
            )
        );
    }

    function payload(
        R.Publication memory p,
        R.Receipt memory receipt,
        R.SourceFacts memory source,
        M.Evidence memory evidence,
        M.Facts memory facts,
        bytes memory environment
    ) public pure returns (bytes memory out) {
        return Input.payload(p, receipt, source, evidence, facts, environment);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../records/StreamSnapshotManifestBytes.sol";
import "../records/StreamReferenceEnvironmentJson.sol";

/// @notice Permissionless preparation of exact immutable file-inventory JSON.
/// @dev Preparation grants no writer/source/archive authority and creates no reference head.
library StreamReferenceRenderPreparation {
    event ReferenceEnvironmentPrepared(
        uint16 schemaVersion, bytes32 indexed environmentId, bytes32 contentHash, uint32 byteLength
    );

    function inventoryId(StreamReferenceRenderTypes.PackageFile[] memory rows, bool relative)
        public
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_FILE_INVENTORY_V1"),
                block.chainid,
                address(this),
                relative,
                rows
            )
        );
    }

    function prepare(
        mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) storage inventories,
        address store,
        bytes32 storeCodeHash,
        StreamReferenceRenderTypes.PackageFile[] memory rows,
        bool relative
    ) public returns (bytes32 id) {
        if (store.code.length == 0 || store.codehash != storeCodeHash) {
            revert StreamReferenceRenderTypes.ReferenceDependency(store);
        }
        id = inventoryId(rows, relative);
        if (inventories[id].contentHash != 0) {
            StreamSnapshotManifestBytes.requireIntact(inventories[id]);
            return id;
        }
        bytes memory raw = bytes(StreamReferenceEnvironmentJson.files(rows, relative));
        StreamSnapshotManifestBytes.retain(inventories[id], store, raw);
    }

    function environment(
        mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) storage inventories,
        StreamReferenceRenderTypes.Environment memory e
    ) public view returns (bytes memory) {
        bytes32 id = environmentIdInternal(e);
        if (inventories[id].contentHash != 0) {
            return StreamSnapshotManifestBytes.read(inventories[id]);
        }
        return _environment(inventories, e);
    }

    function prepareEnvironment(
        mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) storage inventories,
        address store,
        bytes32 storeCodeHash,
        bytes calldata original
    ) public returns (bytes32 id) {
        if (store.code.length == 0 || store.codehash != storeCodeHash) {
            revert StreamReferenceRenderTypes.ReferenceDependency(store);
        }
        StreamReferenceRenderTypes.Environment memory e =
            abi.decode(original[4:], (StreamReferenceRenderTypes.Environment));
        id = environmentIdInternal(e);
        if (inventories[id].contentHash != 0) {
            StreamSnapshotManifestBytes.requireIntact(inventories[id]);
            return id;
        }
        bytes memory raw = _environment(inventories, e);
        if (keccak256(raw) != e.manifestHash || raw.length != e.manifestBytes) {
            revert StreamReferenceRenderTypes.InvalidReferenceRender();
        }
        bytes32 hash = StreamSnapshotManifestBytes.retain(inventories[id], store, raw);
        emit ReferenceEnvironmentPrepared(1, id, hash, uint32(raw.length));
    }

    /// @dev This cache authenticates only the original deterministic serialization of this
    /// complete typed input. No source, writer, dependency, currentness or finality fact is cached.
    /// The compiler-declared map's existing producers never replace a retained entry.
    function environmentIdInternal(StreamReferenceRenderTypes.Environment memory e)
        internal
        view
        returns (bytes32)
    {
        return keccak256(
            abi.encode(
                keccak256("6529STREAM_REFERENCE_ENVIRONMENT_PREPARATION_V1"),
                block.chainid,
                address(this),
                e
            )
        );
    }

    function _environment(
        mapping(bytes32 => StreamSnapshotManifestBytes.Manifest) storage inventories,
        StreamReferenceRenderTypes.Environment memory e
    ) private view returns (bytes memory) {
        bytes memory packageJSON =
            StreamSnapshotManifestBytes.read(inventories[inventoryId(e.packageFiles, true)]);
        bytes memory platformJSON = StreamSnapshotManifestBytes.read(
            inventories[inventoryId(e.platformPrerequisites, false)]
        );
        return StreamReferenceEnvironmentJson.manifestWithAuthenticatedFilesInternal(
            e, packageJSON, platformJSON
        );
    }
}

